SourceCode.Declaration:
/// <summary>
/// CB625_TMSSOPickingListExtraction
/// Class responsible for populating the TMS engine temp table (calculation table) for delivery note
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderPickingList)]
internal final class METTMSEngineLinesTmpBuilder_PickingList extends METTMSEngineLinesTmpBuilder
{
    boolean     isInternalCrossDockOrder;
    boolean     isCSDWarehouse;
    WMSOrderTrans   wmsOrderTrans;

}

Method.Source:
/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init()
{
    super();

    isInternalCrossDockOrder    = headerContract.isInternalCrossDockOrder();
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
protected void initSalesLineVariables(METTMSSourceRecordLineMap _sourceLine)
{
    super(_sourceLine);

    isCSDWarehouse  = inventLocation.METCSDWarehouse;
}

/// <summary>
/// Initialise the sales order line query
/// </summary>
/// <returns><c>Query</c> object</returns>
protected Query initQuery()
{
    Query query = super();
    //If CrossDock or CSD then there might not be a picking list so we don't look at it at all
    if (!isInternalCrossDockOrder && !isCSDWarehouse)
    {
        // extend the query to add a link to salesOrderShipmentLoadLines so that we can get the new PickedQty instead of salesLine.SalesQty
        QueryBuildDataSource qbds = query.dataSourceTable(tableNum(SalesLine));
        QueryBuildDataSource qbdsWMSOrderTrans = qbds.addDataSource(tableNum(WMSOrderTrans));
        qbdsWMSOrderTrans.joinMode(JoinMode::InnerJoin);
        qbdsWMSOrderTrans.addLink(fieldNum(SalesLine, InventTransId), fieldNum(WMSOrderTrans, InventTransId));

        // filter shipment lines for the shipment being confirmed
        qbdsWMSOrderTrans.addRange(fieldNum(WMSOrderTrans, routeId)).value(queryValue(pickingListNumber));
    }

    return query;
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected METTMSSourceRecordLineMap getTablesQueryRun(QueryRun _queryRun)
{
    // call the super to get the SalesLine record
    SalesLine ret = super(_queryRun);
    //If CrossDock or CSD then there might not be a picking list so we don't look at it at all
    if (!isInternalCrossDockOrder && !isCSDWarehouse)
    {
        // get the WMSOrderTrans record from the queryRun object, specific to PickingList
        wmsOrderTrans = _queryRun.get(tableNum(WMSOrderTrans));
    }

    return ret;
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
protected Qty lineShipQty(METTMSSourceRecordLineMap   _sourceLine)
{
    if (isInternalCrossDockOrder || isCSDWarehouse)
    {
        Qty qty = _sourceLine.OrderQty - _sourceLine.pickedInTotalSalesUnit() - _sourceLine.deliveredInTotal();
        return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_sourceLine.ItemId,
                                                                            _sourceLine.InventDimId,
                                                                            qty,
                                                                            InventTableModule::find(_sourceLine.ItemId, ModuleInventPurchSales::Invent).UnitId,
                                                                            _sourceLine.OrderUnit,
                                                                            NoYes::Yes);
    }
    else
    {
        return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_sourceLine.ItemId,
                                                                            _sourceLine.InventDimId,
                                                                            wmsOrderTrans.qty,
                                                                            InventTableModule::find(_sourceLine.ItemId, ModuleInventPurchSales::Invent).UnitId,
                                                                            _sourceLine.OrderUnit,
                                                                            NoYes::Yes);
    }
}
